for (int i = size / 2 - 1; i >= 0; i--) {
        // Start heapifying from the last non-leaf node
        int parent = i;

        // Keep heapifying until we reach a leaf or the subtree is heapified
        while (parent > 0) {
            int smallest = parent;
            int left = 2 * parent + 1;
            int right = 2 * parent + 2;

            // If left child is smaller than parent
            if (left < size && arr[left] < arr[smallest]) {
                smallest = left;
            }

            // If right child is smaller than smallest so far
            if (right < size && arr[right] < arr[smallest]) {
                smallest = right;
            }

            // If smallest is not the parent, swap and continue heapifying
            if (smallest != parent) {
                std::swap(arr[parent], arr[smallest]);
                parent = smallest;

                // Continue checking children
                left = 2 * parent + 1;
                right = 2 * parent + 2;
            } else {
                break;
            }
        }
    }

